    php_info_print_table_row(2, "qthreadruntime total drained", std::to_string(qt_qthreadruntime_total_drained.load(std::memory_order_acquire)).c_str());
    php_info_print_table_row(2, "qthreadruntime total canceled", std::to_string(qt_qthreadruntime_total_canceled.load(std::memory_order_acquire)).c_str());
    php_info_print_table_row(2, "qthreadruntime rejected (full)", std::to_string(qt_qthreadruntime_total_rejected_full.load(std::memory_order_acquire)).c_str());
    php_info_print_table_row(2, "qthreadruntime rejected (stopping)", std::to_string(qt_qthreadruntime_total_rejected_stopping.load(std::memory_order_acquire)).c_str());
    php_info_print_table_row(2, "qthreadruntime total await timeouts", std::to_string(qt_qthreadruntime_total_timeouts.load(std::memory_order_acquire)).c_str());
    php_info_print_table_row(2, "qthreadruntime worker crashes", std::to_string(qt_qthreadruntime_total_worker_crash.load(std::memory_order_acquire)).c_str());
}

static inline qt_qthreadruntime_state *qt_qthreadruntime_fetch_state(zval *zv)
{
    qt_qthreadruntime_object *intern = Z_QTHREADRUNTIME_P(zv);
    if (intern->state == NULL || intern->state->get() == NULL) {
        return NULL;
    }

    return intern->state->get();
}

static bool qt_qthreadruntime_payload_supported(zval *value)
{
    switch (Z_TYPE_P(value)) {
        case IS_RESOURCE:
            return false;
        case IS_OBJECT:
            return !instanceof_function(Z_OBJCE_P(value), zend_ce_closure);
        case IS_ARRAY: {
            zval *entry = NULL;
            ZEND_HASH_FOREACH_VAL(Z_ARRVAL_P(value), entry) {
                if (entry == NULL || !qt_qthreadruntime_payload_supported(entry)) {
                    return false;
                }
            } ZEND_HASH_FOREACH_END();
            return true;
        }
        default:
            return true;
    }
}

static bool qt_qthreadruntime_validate_callable(zval *callable, std::string *error)
{
    if (callable == NULL) {
        if (error != NULL) {
            *error = "must be a callable";
        }
        return false;
    }

    if (Z_TYPE_P(callable) == IS_STRING) {
        if (Z_STRLEN_P(callable) > 0) {
            return true;
        }
        if (error != NULL) {
            *error = "must be a non-empty callable string";
        }
        return false;
    }

    if (Z_TYPE_P(callable) != IS_ARRAY || zend_hash_num_elements(Z_ARRVAL_P(callable)) != 2) {
        if (error != NULL) {
            *error = "must be a non-empty callable string or [class-string, method-string] pair; closures/object callables are not supported yet";
        }
        return false;
    }

    zval *first = zend_hash_index_find(Z_ARRVAL_P(callable), 0);
    zval *second = zend_hash_index_find(Z_ARRVAL_P(callable), 1);
    if (first == NULL
        || second == NULL
        || Z_TYPE_P(first) != IS_STRING
        || Z_TYPE_P(second) != IS_STRING
        || Z_STRLEN_P(first) == 0
        || Z_STRLEN_P(second) == 0
    ) {
        if (error != NULL) {
            *error = "must be [class-string, non-empty method-string] when callable is an array";
        }
        return false;
    }

    zend_string *class_name = Z_STR_P(first);
    zend_class_entry *ce = zend_lookup_class_ex(class_name, NULL, ZEND_FETCH_CLASS_NO_AUTOLOAD);
    if (ce == NULL) {
        if (error != NULL) {
            *error = "class-string callable requires a loaded class in owner runtime";
        }
        return false;
    }

    zend_string *lc_method = zend_string_tolower(Z_STR_P(second));
    zend_function *fn = (zend_function *) zend_hash_find_ptr(&ce->function_table, lc_method);
    zend_string_release(lc_method);
    if (fn == NULL) {
        if (error != NULL) {
            *error = "array callable method was not found on target class";
        }
        return false;
    }

    if ((fn->common.fn_flags & ZEND_ACC_STATIC) == 0) {
        if (error != NULL) {
            *error = "array callable must reference a static method";
        }
        return false;
    }

    return true;
}

static zend_object *qt_qthreadruntime_create_object(zend_class_entry *ce)
{
    qt_qthreadruntime_object *intern = (qt_qthreadruntime_object *) zend_object_alloc(
        sizeof(qt_qthreadruntime_object), ce
    );
    std::shared_ptr<qt_qthreadruntime_state> state = std::make_shared<qt_qthreadruntime_state>();
    intern->state = new std::shared_ptr<qt_qthreadruntime_state>(state);
    qt_qthreadruntime_register(state);

    zend_object_std_init(&intern->std, ce);
    object_properties_init(&intern->std, ce);

    return &intern->std;
}

static void qt_qthreadruntime_free_object(zend_object *object)
{
    qt_qthreadruntime_object *intern = qt_qthreadruntime_from_obj(object);

    if (intern->state != NULL) {
        std::shared_ptr<qt_qthreadruntime_state> state = *intern->state;
        if (state) {
            state->stop(2000);
            qt_qthreadruntime_unregister(state);
        }
        delete intern->state;
        intern->state = NULL;
    }

    zend_object_std_dtor(&intern->std);
}

static HashTable *qt_qthreadruntime_get_gc(zend_object *object, zval **table, int *n)
{
    *table = NULL;
    *n = 0;
    return zend_std_get_properties(object);
}

PHP_METHOD(QThreadRuntime, __construct)
{
    ZEND_PARSE_PARAMETERS_NONE();
}

PHP_METHOD(QThreadRuntime, start)
{
    ZEND_PARSE_PARAMETERS_NONE();

#if !defined(ZTS)
    zend_throw_error(NULL, "Qt\\Core\\QThreadRuntime requires a ZTS PHP build.");
    RETURN_THROWS();
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        zend_throw_error(NULL, "Invalid QThreadRuntime state.");
        RETURN_THROWS();
    }

    if (!state->start()) {
        zend_throw_error(NULL, "Failed to start worker runtime.");
        RETURN_THROWS();
    }
#endif
}

PHP_METHOD(QThreadRuntime, setBootstrapScript)
{
    zend_string *path = NULL;
    ZEND_PARSE_PARAMETERS_START(0, 1)
        Z_PARAM_OPTIONAL
        Z_PARAM_STR_OR_NULL(path)
    ZEND_PARSE_PARAMETERS_END();

#if !defined(ZTS)
    zend_throw_error(NULL, "Qt\\Core\\QThreadRuntime requires a ZTS PHP build.");
    RETURN_THROWS();
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        zend_throw_error(NULL, "Invalid QThreadRuntime state.");
        RETURN_THROWS();
    }

    std::string set_error;
    std::string value = path != NULL ? std::string(ZSTR_VAL(path), ZSTR_LEN(path)) : std::string();
    if (!state->setBootstrapScript(value, &set_error)) {
        zend_throw_error(NULL, "%s", set_error.c_str());
        RETURN_THROWS();
    }
#endif
}

PHP_METHOD(QThreadRuntime, submit)
{
    zval *callable = NULL;
    zval *args = NULL;

    ZEND_PARSE_PARAMETERS_START(1, 2)
        Z_PARAM_ZVAL(callable)
        Z_PARAM_OPTIONAL
        Z_PARAM_ARRAY(args)
    ZEND_PARSE_PARAMETERS_END();

#if !defined(ZTS)
    zend_throw_error(NULL, "Qt\\Core\\QThreadRuntime requires a ZTS PHP build.");
    RETURN_THROWS();
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        zend_throw_error(NULL, "Invalid QThreadRuntime state.");
        RETURN_THROWS();
    }

    std::string callable_error;
    if (!qt_qthreadruntime_validate_callable(callable, &callable_error)) {
        zend_argument_value_error(1, "%s", callable_error.c_str());
        RETURN_THROWS();
    }

    if (args != NULL && !qt_qthreadruntime_payload_supported(args)) {
        zend_argument_value_error(
            2,
            "contains unsupported values for cross-runtime transport (resources/closures are not supported)"
        );
        RETURN_THROWS();
    }

    if (!state->start()) {
        zend_throw_error(NULL, "Failed to start worker runtime.");
        RETURN_THROWS();
    }

    zval callable_input;
    ZVAL_COPY(&callable_input, callable);
    std::string callable_payload;
    if (!qt_qthreadruntime_state::serializeValue(&callable_input, &callable_payload)) {
        zval_ptr_dtor(&callable_input);
        zend_throw_error(NULL, "Failed to serialize worker callable.");
        RETURN_THROWS();
    }
    zval_ptr_dtor(&callable_input);

    zval serialized_args_input;
    if (args != NULL) {
        ZVAL_COPY(&serialized_args_input, args);
    } else {
        array_init(&serialized_args_input);
    }

    std::string args_payload;
    if (!qt_qthreadruntime_state::serializeValue(&serialized_args_input, &args_payload)) {
        zval_ptr_dtor(&serialized_args_input);
        zend_throw_error(NULL, "Failed to serialize worker arguments.");
        RETURN_THROWS();
    }
    zval_ptr_dtor(&serialized_args_input);

    uint64_t job_id = 0;
    std::string submit_error;
    if (!state->submit(
        std::move(callable_payload),
        std::move(args_payload),
        &job_id,
        &submit_error
    )) {
        zend_throw_error(NULL, "%s", submit_error.c_str());
        RETURN_THROWS();
    }

    RETURN_LONG((zend_long) job_id);
#endif
}

PHP_METHOD(QThreadRuntime, await)
{
    zend_long job_id = 0;
    zend_long timeout_ms = 0;

    ZEND_PARSE_PARAMETERS_START(1, 2)
        Z_PARAM_LONG(job_id)
        Z_PARAM_OPTIONAL
        Z_PARAM_LONG(timeout_ms)
    ZEND_PARSE_PARAMETERS_END();

#if !defined(ZTS)
    zend_throw_error(NULL, "Qt\\Core\\QThreadRuntime requires a ZTS PHP build.");
    RETURN_THROWS();
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        zend_throw_error(NULL, "Invalid QThreadRuntime state.");
        RETURN_THROWS();
    }

    qt_qthreadruntime_result result;
    qt_qthreadruntime_await_status status = state->await((uint64_t) job_id, timeout_ms, &result);
    if (status == qt_qthreadruntime_await_status::timeout) {
        RETURN_NULL();
    }
    if (status == qt_qthreadruntime_await_status::unknown) {
        zend_throw_error(NULL, "Unknown job id %" ZEND_LONG_FMT ".", job_id);
        RETURN_THROWS();
    }

    if (result.canceled) {
        RETURN_FALSE;
    }

    if (!result.success) {
        zend_class_entry *exception_ce = zend_exception_get_default();
        if (!result.error.class_name.empty()) {
            zend_string *class_name = zend_string_init(result.error.class_name.c_str(), result.error.class_name.size(), 0);
            zend_class_entry *resolved_ce = zend_lookup_class_ex(class_name, NULL, 0);
            zend_string_release(class_name);
            if (resolved_ce != NULL && instanceof_function(resolved_ce, zend_ce_throwable)) {
                exception_ce = resolved_ce;
            }
        }

        const std::string &message = result.error.message.empty()
            ? std::string("Worker runtime execution failed.")
            : result.error.message;
        zend_throw_exception(exception_ce, message.c_str(), result.error.code);
        RETURN_THROWS();
    }

    zval payload;
    if (!qt_qthreadruntime_state::unserializeValue(result.payload, &payload)) {
        zend_throw_error(NULL, "Failed to unserialize worker result payload.");
        RETURN_THROWS();
    }

    ZVAL_COPY_VALUE(return_value, &payload);
#endif
}

PHP_METHOD(QThreadRuntime, cancel)
{
    zend_long job_id = 0;
    ZEND_PARSE_PARAMETERS_START(1, 1)
        Z_PARAM_LONG(job_id)
    ZEND_PARSE_PARAMETERS_END();

#if !defined(ZTS)
    RETURN_FALSE;
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        RETURN_FALSE;
    }

    RETURN_BOOL(state->cancel((uint64_t) job_id));
#endif
}

PHP_METHOD(QThreadRuntime, stop)
{
    zend_long timeout_ms = 5000;
    ZEND_PARSE_PARAMETERS_START(0, 1)
        Z_PARAM_OPTIONAL
        Z_PARAM_LONG(timeout_ms)
    ZEND_PARSE_PARAMETERS_END();

#if !defined(ZTS)
    RETURN_FALSE;
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        RETURN_FALSE;
    }

    RETURN_BOOL(state->stop(timeout_ms));
#endif
}

PHP_METHOD(QThreadRuntime, isRunning)
{
    ZEND_PARSE_PARAMETERS_NONE();

#if !defined(ZTS)
    RETURN_FALSE;
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        RETURN_FALSE;
    }

    RETURN_BOOL(state->isRunning());
#endif
}

PHP_METHOD(QThreadRuntime, stats)
{
    ZEND_PARSE_PARAMETERS_NONE();

#if !defined(ZTS)
    array_init(return_value);
    add_assoc_bool(return_value, "running", false);
#else
    qt_qthreadruntime_state *state = qt_qthreadruntime_fetch_state(ZEND_THIS);
    if (state == NULL) {
        array_init(return_value);
        add_assoc_bool(return_value, "running", false);
        return;
    }

    state->fillStats(return_value);
#endif
}

