PHP_MINIT_FUNCTION(qt_qthreadruntime)
{
    zend_class_entry ce;
    INIT_NS_CLASS_ENTRY(ce, "Qt\\Core", "QThreadRuntime", qt_qthreadruntime_methods);
    ce.create_object = qt_qthreadruntime_create_object;

    qt_ce_QThreadRuntime = zend_register_internal_class(&ce);
    qt_ce_QThreadRuntime->ce_flags |= ZEND_ACC_FINAL;

    memcpy(&qt_qthreadruntime_handlers, &std_object_handlers, sizeof(zend_object_handlers));
    qt_qthreadruntime_handlers.offset = XtOffsetOf(qt_qthreadruntime_object, std);
    qt_qthreadruntime_handlers.free_obj = qt_qthreadruntime_free_object;
    qt_qthreadruntime_handlers.clone_obj = NULL;
    qt_qthreadruntime_handlers.get_gc = qt_qthreadruntime_get_gc;
    qt_ce_QThreadRuntime->default_object_handlers = &qt_qthreadruntime_handlers;

    return SUCCESS;
}
